import { Mesh, PlaneGeometry, Object3D, DoubleSide, SRGBColorSpace } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { TimelineMax } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {import('three/webgpu').Object3D} THREEObject3D
 * @typedef {Object} NodeConfig
 * @property {Object} [assets]
 * @property {string} [assets.imageUrl]
 * @property {Object} [scenePlacement]
 * @property {Array<number>} [scenePlacement.position]
 * @property {Array<number>} [scenePlacement.rotation]
 * @property {Array<number>} [scenePlacement.scale]
 * @property {Object} [visual]
 * @property {Object} [visual.colors]
 *
 * @typedef {Object} NodeContext
 * @property {{ load: (url:string)=>import('three').Texture }} textureLoader
 * @property {{ [key:string]: (target:THREEObject3D, params:any)=>void }} primitives
 * @property {{ fontAtlas: any }} fontAtlas
 */

/**
 * Creates a textured plane node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREEObject3D}
 */
export default function createNode(config, ctx) {
  // --- Geometry --------------------------------------------------------------
  const geometry = new PlaneGeometry(1, 1);

  // --- Texture ---------------------------------------------------------------
  const imageUrl = (config.assets && config.assets.imageUrl) || '';
  const tex = ctx.textureLoader.load(imageUrl);
  tex.colorSpace = SRGBColorSpace;
  tex.wrapS = tex.wrapT = tex.repeat ? tex.repeat : tex.wrapS;
  tex.needsUpdate = true;

  // --- Material ---------------------------------------------------------------
  const material = new MeshBasicNodeMaterial({
    map: texture(tex),
    side: DoubleSide,
  });

  // --- Mesh -------------------------------------------------------------------
  const mesh = new Mesh(geometry, material);

  // Apply scene placement
  const pos = (config.scenePlacement && config.scenePlacement.position) || [0, 0, 0];
  const rot = (config.scenePlacement && config.scenePlacement.rotation) || [0, 0, 0];
  const scl = (config.scenePlacement && config.scenePlacement.scale) || [1, 1, 1];

  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // --- User Data --------------------------------------------------------------
  mesh.userData.handlers = {};

  // Store any timelines we might create in the future
  /** @type {TimelineMax[]} */
  const timelines = [];

  // --- Cleanup ---------------------------------------------------------------
  mesh.userData.cleanup = () => {
    // Kill GSAP timelines
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;

    // Dispose Three.js resources
    material.dispose();
    geometry.dispose();
    // Do NOT dispose the texture here – it may be shared via the loader cache
  };

  // No cinematic primitives to apply for this node (as per spec)

  return mesh;
}
